{
  "name": "@kitlangton/skulk",
  "version": "0.1.0",
  "description": "Durable timers, event triggers, and conditional session wake-ups for OpenCode agents.",
  "license": "MIT",
  "author": "Kit Langton",
  "homepage": "https://skulk.kitlangton.com",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/kitlangton/skulk.git"
  },
  "bugs": {
    "url": "https://github.com/kitlangton/skulk/issues"
  },
  "keywords": [
    "opencode",
    "agents",
    "ai-agents",
    "scheduler",
    "cli",
    "launchd",
    "systemd",
    "github-actions",
    "npm",
    "wake"
  ],
  "type": "module",
  "bin": {
    "skulk": "src/cli.ts",
    "wake": "src/cli.ts"
  },
  "files": [
    "src",
    "skills",
    "LICENSE",
    "README.md"
  ],
  "engines": {
    "bun": ">=1.2.0"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "deploy": "wrangler deploy",
    "prepublishOnly": "bun run typecheck && bun run test"
  },
  "devDependencies": {
    "@types/bun": "latest",
    "typescript": "5.8.2",
    "wrangler": "4.150.0"
  }
}
